head.script:
scwin.inc1_onpageload = function () {
    var log = $p.top().scwin.log;
    log("--- [include1] onpageload ---");
    log("  INC1_name = [" + scvar.INC1_name + "] (ONE 기대)");
    log("  TOP_name = [" + scvar.TOP_name + "] (TOP 기대 - 부모 변수 보존)");
    log("  키 목록 = " + Object.keys(scvar).join(", "));
};
